import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"斯干","description":"","frontmatter":{"title":"斯干","date":"2026-11-08T00:00:00.000Z","seq":29,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/斯干.md","filePath":"blogs/诗经·小雅/斯干.md"}'),p={name:"blogs/诗经·小雅/斯干.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="斯干" tabindex="-1">斯干 <a class="header-anchor" href="#斯干" aria-label="Permalink to &quot;斯干&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　鸿雁之什</p><div class="poem"><p class="poem-stanza">秩秩斯干，幽幽南山。如竹苞矣，如松茂矣。兄及弟矣，式相好矣，无相犹矣。</p><p class="poem-stanza">似续妣祖，筑室百堵，西南其户。爰居爰处，爰笑爰语。</p><p class="poem-stanza">约之阁阁，椓之橐橐。风雨攸除，鸟鼠攸去，君子攸芋。</p><p class="poem-stanza">如跂斯翼，如矢斯棘，如鸟斯革，如翚斯飞，君子攸跻。</p><p class="poem-stanza">殖殖其庭，有觉其楹。哙哙其正，哕哕其冥。君子攸宁。</p><p class="poem-stanza">下莞上簟，乃安斯寝。乃寝乃兴，乃占我梦。吉梦维何？维熊维罴，维虺维蛇。</p><p class="poem-stanza">大人占之：维熊维罴，男子之祥；维虺维蛇，女子之祥。</p><p class="poem-stanza">乃生男子，载寝之床。载衣之裳，载弄之璋。其泣喤喤，朱芾斯皇，室家君王。</p><p class="poem-stanza">乃生女子，载寝之地。载衣之裼，载弄之瓦。无非无仪，唯酒食是议，无父母诒罹。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
